style.css:
@-moz-document domain("open.spotify.com") {
/* === MAIN BACKGROUND === */
body::before {
    content: "";
    position: fixed;
    inset: 0;
    background: url("https://i.pinimg.com/736x/56/5e/28/565e2813775e932d948f3bcb6c234d70.jpg") center/cover no-repeat;
    filter: blur(0px) brightness(0.75);
    z-index: -9999;
}

/* Remove Spotify default backgrounds */
body,
.main-view-container,
.Root__main-view,
.Root,
.main-home-content,
.main-nowPlayingView-section,
.main-yourLibraryX-libraryContainer,
.main-trackList-trackListHeader,
.main-entityHeader-backgroundColor,
.main-topBar-background,
.main-navBar-navBar {
    background: transparent !important;
}

/* === TEXT === */
* {
    color: white !important;
}

/* === SIDEBAR === */
.Root__nav-bar,
.main-yourLibraryX-libraryContainer {
    background: rgba(255, 192, 203, 0.18) !important;
    backdrop-filter: blur(18px);
    border-radius: 20px;
}

/* === PLAYER BAR === */
.Root__now-playing-bar {
    background: rgba(255, 182, 193, 0.25) !important;
    backdrop-filter: blur(20px);
    border-top: 1px solid rgba(255,255,255,0.15);
}

/* === BUTTONS === */
button,
.Button,
.main-playButton-PlayButton,
.control-button,
.main-topBar-button,
.main-genericButton-button {
    background: #f7bfd7 !important;
    color: white !important;
    border-radius: 999px !important;
    border: none !important;
    transition: 0.2s ease;
}

button:hover,
.Button:hover,
.main-playButton-PlayButton:hover {
    background: #f4aac9 !important;
    transform: scale(1.05);
}

/* === CARDS / PLAYLISTS === */
.main-card-card,
.main-trackList-trackListRow,
.main-entityHeader-container {
    background: rgba(255, 192, 203, 0.12) !important;
    backdrop-filter: blur(16px);
    border-radius: 20px !important;
}

/* === SEARCH BAR === */
input,
.searchInput__input {
    background: rgba(255,255,255,0.15) !important;
    color: white !important;
    border-radius: 15px !important;
}

/* === SCROLLBAR === */
::-webkit-scrollbar-thumb {
    background: #f7bfd7 !important;
    border-radius: 10px;
}

/* === EXTRA CUTE GLOW === */
.main-playButton-PlayButton,
button {
    box-shadow: 0 0 12px rgba(255, 192, 203, 0.5);
}
}
